var builder=WebApplication.CreateBuilder(args);builder.Services.AddHealthChecks();builder.Services.AddOpenApi();builder.Services.AddSingleton<PostgresProbe>();builder.Services.AddScoped<BootstrapService>();builder.Services.AddSingleton<JwtTokenService>();builder.Services.AddScoped<AuthService>();builder.Services.AddScoped<AgendaService>();builder.Services.AddScoped<OnlineSessionValidator>();builder.Services.AddScoped<DevicePairingService>();builder.Services.AddScoped<DeviceManagementService>();builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=JwtTokenService.Issuer,ValidateAudience=true,ValidAudience=JwtTokenService.Audience,ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(JwtTokenService.GetSigningKey(builder.Configuration)),ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30)};o.Events=new JwtBearerEvents{OnTokenValidated=async c=>{var v=c.HttpContext.RequestServices.GetRequiredService<OnlineSessionValidator>();if(!await v.IsCurrentAsync(c.Principal!,c.HttpContext.RequestAborted))c.Fail("Session revoked or security version changed.");}};});builder.Services.AddAuthorization();var app=builder.Build();if(app.Environment.IsDevelopment())app.MapOpenApi();app.UseAuthentication();app.UseAuthorization();app.MapGet("/api/v1/health",()=>Results.Ok(new{status="ok",service="BCK Agenda API",version="0.5.0",serverTimeUtc=DateTimeOffset.UtcNow}));app.MapGet("/api/v1/health/database",async(PostgresProbe p,CancellationToken ct)=>{var r=await p.CheckAsync(ct);return r.Ready?Results.Ok(new{status="ok",database=r.Database,foundationMigration="applied"}):Results.Json(new{status="unavailable",code="DATABASE_UNAVAILABLE"},statusCode:503);});app.MapGet("/api/v1/system/time",()=>Results.Ok(new{serverTimeUtc=DateTimeOffset.UtcNow}));app.MapPost("/api/v1/bootstrap/company",async(CreateCompanyRequest r,BootstrapService s,CancellationTo