ults.Ok(await s.ListServicesAsync(GroupId(u),ct)));api.MapGet("/appointments/availability",async(Guid professionalUserId,DateTimeOffset startsAt,DateTimeOffset endsAt,ClaimsPrincipal u,AgendaService s,CancellationToken ct)=>{if(!CanAccessProfessional(u,professionalUserId))return Results.Forbid();try{return Results.Ok(await s.CheckAvailabilityAsync(GroupId(u),professionalUserId,startsAt,endsAt,ct));}catch(ArgumentException e){return Results.BadRequest(new{code="VALIDATION_ERROR",message=e.Message});}});api.MapPost("/appointments",async(CreateAppointmentRequest r,ClaimsPrincipal u,AgendaService s,IConfiguration cfg,CancellationToken ct)=>{if(!CanAccessProfessional(u,r.ProfessionalUserId))return Results.Forbid();if(r.ForceConflict&&!await CanForceConflictAsync(u,cfg,ct))return Results.Forbid();try{var x=await s.CreateAppointmentAsync(r with{GroupId=GroupId(u),CreatedByUserId=UserId(u)},ct);return Results.Created($"/api/v1/appointments/{x.Id}",x);}catch(InvalidOperationException e)when(e.Message=="APPOINTMENT_CONFLICT"){return Results.Conflict(new{code="APPOINTMENT_CONFLICT",message="Já existe atendimento do profissional nesse intervalo."});}catch(ArgumentException e){return Results.BadRequest(new{code="VALIDATION_ERROR",message=e.Message});}});api.MapGet("/appointments",async(Guid professionalUserId,DateTimeOffset from,DateTimeOffset to,ClaimsPrincipal u,AgendaService s,CancellationToken ct)=>{if(!CanAccessProfessional(u,professionalUserId))return Results.Forbid();return Results.Ok(await s.ListAppointmentsAsync(GroupId(u),professionalUserId,from,to,ct));});app.MapHealthChecks("/health");app.Run();static Guid GroupId(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue("group_id")??throw new UnauthorizedAccessException());static Guid UserId(ClaimsPrincipal u)=>Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)??u.FindFirstValue("sub")??throw new UnauthorizedAccessException());static bool IsAdmin(ClaimsPrincipal u)=>string.Equals(u.FindFirstValue("profile"),"ADMIN",String